function sourceLines82(){const s=SubReport82,seen=new Set(),journals=[...(reviewStaffJournals||[]),...workspaceReviewJournals()];return journals.filter(j=>String(j.owner_id)===s.user&&(s.status==='all'||j.status===s.status)).flatMap(j=>(j.lines||[]).map(l=>({...l,sourceStatus:j.status,journalId:j.id}))).filter(l=>{const date=String(l.transaction_date||l.date||'').slice(0,10),key=String(l.id||l.workspace_entry_no||[l.journalId,date,l.account_id,l.fund_account_id,l.amount,l.memo].join('|'));if(seen.has(key))return false;seen.add(key);return date>=s.from&&date<=s.to&&(!s.fund||String(l.fund_account_id)===s.fund)&&l.status!=='voided'}).sort((a,b)=>String(a.transaction_date||a.date).localeCompare(String(b.transaction_date||b.date))||String(a.workspace_entry_no||a.id).localeCompare(String(b.workspace_entry_no||b.id)));}
