function renderFinanceBase82(notice){const d=Finance82,options=accountDataCurrencies79().filter((c,i,a)=>c&&a.indexOf(c)===i).map(c=>[c,c]);if(!options.length)options.push(['LAK','LAK']);mount82('report-financing82','Financing & Budget Requests','Document requested support, allocations and account movements by currency.',notice+`<form id="financeForm82"><div class="fields82">${select82('Report type','mode',d.mode,[['request','Budget Request'],['utilization','Financing Utilization']])}${field82('Reference','reference',d.reference,'text','required')}${field82('Report date','date',d.date,'date','required')}${field82('Recipient / financing source','recipient',d.recipient,'text','required')}${field82('Purpose','purpose',d.purpose,'text','required')}${field82('Reviewer','reviewer',d.reviewer)}${field82('Notes / exchange-rate evidence','notes',d.notes)}</div></form>`+section82('Funding Items',`<form id="financeLine82" onsubmit="event.preventDefault();financeLine82()"><div class="fields82">${field82('Category','category','','text','required')}${field82('Description','description','','text','required')}${select82('Currency','currency','LAK',options)}${field82('Amount','amount','','number','min="0.01" step="0.01" required')}${field82('Reference','reference','')}<button type="submit">Add Item</button></div></form>`+table82(['Category','Description','Currency','Amount','Reference','Action'],d.lines.map((l,i)=>[esc82(l.category),esc82(l.description),esc82(l.currency),money82(l.amount),esc82(l.reference),action82('Remove',`readFinance82();Finance82.lines.splice(${i},1);renderWork82()`)])),action82('Add Finalized Payroll','financePayroll82()'))+section82('Funding / Account Movement',`<form id="financeMove82" onsubmit="event.preventDefault();financeMovement82()"><div class="fields82">${field82('Account / source','account','','text','required')}${select82('Currency','currency','LAK',options)}${field82('Inflow','inflow',0,'number','min="0" step="0.01"')}${field82('Outflow','outflow',0,'number','min="0" step="0.01"')}${field82('Reference','reference','','text','required')}<button type="submit">Add Movement</button></div></form>`+table82(['Account','Currency','Inflow','Outflow','Remaining','Reference','Action'],d.movements.map((m,i)=>[esc82(m.account),esc82(m.currency),money82(m.inflow),money82(m.outflow),money82(m.inflow-m.outflow),esc82(m.reference),action82('Remove',`readFinance82();Finance82.movements.splice(${i},1);renderWork82()`)])))+section82('Saved Financing Reports',table82(['Reference','Date','Recipient','Type','Action'],Work82.reports.filter(r=>r.data.kind==='finance').map(r=>[esc82(r.data.reference),esc82(formatAppDate(r.data.date)),esc82(r.data.recipient),esc82(r.data.mode),action82('Open',`openOperational82('${r.id}')`)]))),action82('New Report','newFinance82()')+action82('Print / Save PDF','printFinance82()')+action82('Save Report',"saveFinance82()",true))}
