function payrollVoucher82(run,x){const leave=(run.leaveSnapshot||Work82.leaves.filter(r=>r.data.status==='approved'&&r.data.month===run.month).map(r=>r.data)).filter(r=>r.employeeId===x.employeeId);return `<article class="voucher82">${run.isSample?'<p class="notice82 warn82"><strong>SAMPLE — NOT FOR PAYMENT</strong></p>':''}<h2>Salary Payment Voucher · ${esc82(run.month)}</h2><p>${esc82(run.reference)} · ${run.status==='finalized'?'FINALIZED CALCULATION':'DRAFT — NOT FINALIZED'}</p><p><strong>${esc82(x.employee.name)}</strong> · ${esc82(x.employee.code)} · ${esc82(x.employee.position)}</p>${table82(['Description','Amount','Currency'],[['Contract salary',money82(x.contract),esc82(x.currency)],['LAK per 1 '+esc82(x.currency),money82(x.rate),'LAK'],['Overtime',money82(x.overtime),'LAK'],['Taxable allowance',money82(x.allowance),'LAK'],['Late time deduction',money82(x.late),'LAK'],['Unpaid days deduction ('+money82(x.unpaidDays)+' days)',money82(x.absence),'LAK'],['Other internal deductions',money82(x.penalty+x.other),'LAK'],['Gross earnings',money82(x.gross),'LAK'],['Employee SSO',money82(x.employeeSso),'LAK'],['Employee PIT',money82(x.employeePit),'LAK'],['Net pay',money82(x.net),'LAK'],['Reimbursement',money82(x.reimbursement),'LAK'],['Paid holiday / leave (already included)',money82(x.paidLeaveValue),'LAK'],['Less cash advance recovery',money82(x.cashAdvance??x.advance),'LAK'],['Less loan repayment',money82(x.loanRecovery),'LAK'],['Final amount to pay','<strong>'+money82(x.paidAmount)+'</strong>',esc82(x.currency)]])}<p>Rate date: ${esc82(run.rateDate)} · Source: ${esc82(run.rateSource||'LAK contract — no conversion')}<br>Approved leave: ${esc82(leave.map(l=>l.type+' '+l.days+' days ('+(l.paid==='yes'?'paid':'unpaid')+')').join('; ')||'None recorded')}. Paid leave is included in monthly salary.<br>Supporting reference: ${esc82(run.rows.find(r=>r.employeeId===x.employeeId)?.input.note||'—')}</p><p>I acknowledge receipt of __________________ ${esc82(x.currency)} on __________________.</p><div class="signatures82"><div>Employee signature</div><div>Authorized by</div><div>Witness / paid by</div></div><p>Printing this voucher does not mark the salary paid or post a journal entry.</p></article>`}
