function importDraft82(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>5e6)throw Error('Choose a payroll backup under 5 MB.');const parsed=JSON.parse(await file.text());if(parsed.format!=='oonjai-backup-82'||parsed.kind!=='payroll'||!Array.isArray(parsed.data?.rows)||!/^\d{4}-\d{2}$/.test(parsed.data.month))throw Error('This is not a payroll backup.');for(const r of parsed.data.rows)if(!r.employeeId||!r.employee?.name||!r.employee.currency||!Array.isArray(r.input?.attendance))throw Error('Backup contains an invalid employee row.');Work82.run={...parsed.data,status:'draft',reviewed:false};delete Work82.run.results;delete Work82.run.config;delete Work82.run.finalizedAt;Work82.runRecord=null;switchTab('payroll-entries');showCenterStatus('Restored as a draft. Review Settings and save to create a new record.')}catch(e){showCenterStatus(e.message,true)}};input.click()}

